// Maximizing Spatial Locality (Row-major order in C/C++)
#define N 1024
int matrix[N][N];
// Access elements sequentially (unit stride)
// Optimal cache line reuse
void access_rows() {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            matrix[i][j] = 1;
        }
    }
}

// Minimizing Spatial Locality (Column-major access pattern)
// High cache misses due to large strides
void access_cols() {
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            matrix[i][j] = 1; // Jumps across memory quickly
        }
    }
}

// Maximizing Temporal Locality
// Reuse of variable 's' before it is evicted from L1/Registers
int compute_sum(const int* data, int size) {
    int s = 0; // High Temporal Locality
    for (int i = 0; i < size; ++i) {
        s += data[i];
    }
    return s;
}

// Cache line alignment hint (GCC extension example)
struct __attribute__((aligned(64))) CacheAlignedData {
    int x;
    int y;
};
